"""gRPC helpers: generated stubs, cached client channels, a metrics/logging
server interceptor, and correlation-id propagation via metadata."""
import logging
import threading
import time
from concurrent import futures

import grpc

from . import config
from .observability import GRPC_LATENCY, GRPC_REQUESTS, correlation_id

# Generated by grpc_tools.protoc at image build time (see services/Dockerfile)
import campus_pb2  # noqa: E402  (on PYTHONPATH via /app/gen)
import campus_pb2_grpc  # noqa: E402

log = logging.getLogger("grpc")

_channels: dict = {}
_lock = threading.Lock()


def channel(target: str) -> grpc.Channel:
    with _lock:
        ch = _channels.get(target)
        if ch is None:
            ch = grpc.insecure_channel(target, options=[
                ("grpc.keepalive_time_ms", 30000),
                ("grpc.lb_policy_name", "round_robin"),
            ])
            _channels[target] = ch
        return ch


def metadata():
    return (("x-correlation-id", correlation_id.get()),)


def partition_stub() -> campus_pb2_grpc.PartitionServiceStub:
    return campus_pb2_grpc.PartitionServiceStub(channel(config.PARTITION_GRPC))


def availability_stub() -> campus_pb2_grpc.AvailabilityServiceStub:
    return campus_pb2_grpc.AvailabilityServiceStub(channel(config.AVAILABILITY_GRPC))


class ObservabilityInterceptor(grpc.ServerInterceptor):
    """Counts and times every unary call; restores the caller's correlation id."""

    def intercept_service(self, continuation, handler_call_details):
        handler = continuation(handler_call_details)
        if handler is None or handler.unary_unary is None:
            return handler
        method = handler_call_details.method.rsplit("/", 1)[-1]
        md = dict(handler_call_details.invocation_metadata or ())
        cid = md.get("x-correlation-id", "-")
        inner = handler.unary_unary

        def wrapper(request, context):
            token = correlation_id.set(cid)
            start = time.perf_counter()
            code = "OK"
            try:
                return inner(request, context)
            except Exception:
                code = "INTERNAL"
                log.exception(f"gRPC {method} failed")
                raise
            finally:
                if context.code() not in (None, grpc.StatusCode.OK):
                    code = context.code().name
                elapsed = time.perf_counter() - start
                GRPC_REQUESTS.labels(config.SERVICE_NAME, method, code).inc()
                GRPC_LATENCY.labels(config.SERVICE_NAME, method).observe(elapsed)
                log.info(f"gRPC {method} -> {code}",
                         extra={"fields": {"grpcMethod": method, "grpcCode": code,
                                           "duration_ms": round(elapsed * 1000, 1)}})
                correlation_id.reset(token)

        return grpc.unary_unary_rpc_method_handler(
            wrapper,
            request_deserializer=handler.request_deserializer,
            response_serializer=handler.response_serializer,
        )


def serve(register_fn, port: int = None, workers: int = 16) -> grpc.Server:
    """Start a gRPC server in background threads; returns the server."""
    server = grpc.server(
        futures.ThreadPoolExecutor(max_workers=workers),
        interceptors=[ObservabilityInterceptor()],
        # Force clients to reconnect every 30s so they re-resolve DNS and
        # start using pods that the HPA added.
        options=[("grpc.max_connection_age_ms", 30000), ("grpc.max_connection_age_grace_ms", 5000)],
    )
    register_fn(server)
    server.add_insecure_port(f"[::]:{port or config.GRPC_PORT}")
    server.start()
    log.info(f"gRPC server listening on :{port or config.GRPC_PORT}")
    return server
